// claim-office.spec.ts
import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("Claim Office", () => {
  describe("Quote: base premiums", () => {
    it.todo("should return 5 G for an empty item list (processing fee only)");
    it.todo("should return 105 G for a single plain sword (100 base + 5 fee)");
    it.todo("should return 65 G for a single plain amulet (60 base + 5 fee)");
    it.todo("should return 85 G for a single plain staff (80 base + 5 fee)");
    it.todo("should return 45 G for a single plain potion (40 base + 5 fee)");
    it.todo("should sum base premiums for multiple items (sword + amulet → 165 G)");
    it.todo("should throw an error for an unknown item type");
  });

  describe("Quote: component block pricing", () => {
    it.todo("should charge 25 G base premium per component (2 runes → 50 G base)");
    it.todo("should charge 60 G base premium for a block of exactly 3 alike components (3 runes)");
    it.todo("should not apply the block to 4 alike components (4 runes → 100 G base)");
    it.todo("should apply one block within 7 alike components (7 runes → 175 G base)");
    it.todo("should not form a block from different component types (2 runes + 1 moonstone → 75 G base)");
    it.todo("should form separate blocks per component type (3 runes + 3 moonstones → 120 G base)");
  });

  describe("Quote: item-specific modifiers", () => {
    it.todo("should add 50 % curse surcharge on the cursed item's base premium");
    it.todo("should add 30 % surcharge for enchantment level of exactly 5");
    it.todo("should not add a high-enchantment surcharge for enchantment level 4");
    it.todo("should apply both curse and high-enchantment surcharges to the same item");
    it.todo("should apply the curse surcharge only to the cursed item's base premium, not the policy total (cursed sword + plain amulet → 210 G before policy modifiers and fee)");
  });

  describe("Quote: policy-wide modifiers", () => {
    it.todo("should always add 10 % first-insurance surcharge to the policy base premium");
    it.todo("should apply 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
    it.todo("should not apply the loyalty discount for a customer with fewer than 2 years");
    it.todo("should apply 15 % follow-up discount on each quote after the customer's first");
  });

  describe("Quote: rounding", () => {
    it.todo("should round the final premium up (197.5 G → 198 G)");
  });

  describe("Quote: integration", () => {
    it.todo("should quote 165 G for a newcomer's cursed steel sword with enchantment 3");
    it.todo("should quote 160 G for a 3-year customer's second quote of a cursed sword with enchantment 7");
  });

  describe("Claim: standard reimbursement", () => {
    it.todo("should pay damage minus 100 G deductible for a regular item (steel sword ench 3, damage 500 → 400)");
    it.todo("should pay damage minus deductible for a component (rune, damage 200 → 100)");
  });

  describe("Claim: special clauses", () => {
    it.todo("should reimburse 50 % before deductible for enchantment level ≥ 8 (steel sword ench 9, damage 1000 → 400)");
    it.todo("should reimburse fully before deductible for dragon material (dragon sword ench 5, damage 800 → 700)");
    it.todo("should apply the 50 % rule when both clauses apply (dragon sword ench 9, damage 1000 → 400)");
    it.todo("should apply the 50 % rule at exactly enchantment 8 (dragon sword ench 8, damage 1000 → 400)");
  });

  describe("Claim: multi-item damage", () => {
    it.todo("should apply the deductible once per damaged item (sword 500 + amulet 300 → 600)");
  });

  describe("Claim: payout cap", () => {
    it.todo("should cap the policy at twice the insurance sum (single sword → cap 2000)");
    it.todo("should report the remaining cap after a claim (sword, claim 1500 → payout 1400, remaining 600)");
    it.todo("should limit a payout to the remaining cap on successive claims (second claim 1500 → payout 600, remaining 0)");
  });

  describe("Claim: rounding", () => {
    it.todo("should round the final payout down (350.5 G → 350 G)");
  });

  describe("Claim: errors", () => {
    it.todo("should throw when a damage entry references an item not in the policy");
    it.todo("should throw when more damage entries of a type exist than items insured");
    it.todo("should throw for a negative damage amount");
  });
});

